        Order latest = null;
        for (Order order : orders.all()) {
            if (customerId.equals(order.customerId())
                    && (latest == null || order.placedAt().isAfter(latest.placedAt()))) {
                latest = order;
            }
        }
        if (latest == null) {
            return OrderSummaryLookup.notFound();
        }
        return OrderSummaryLookup.found(
